begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('a2200000-0000-4000-8000-000000000001','access@example.invalid');
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining','30','Initial energy');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','one','{"kind":"fixture"}',12,1)->>'reason','allowed','Canonical trusted reservation');
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining','18','Balance consumed');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','one','{"kind":"fixture"}',12,1)->>'reason','allowed','Stable retry');
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining','18','No double spend');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','one','{"kind":"changed"}',12,1)->>'reason','conflict','Source bound');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','higher','{"kind":"fixture"}',12,3)->>'reason','premium','Higher level blocked');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','large','{"kind":"fixture"}',20,1)->>'reason','limit','Cannot partially spend');
update access_energy set balance=0,refilled_at=now()-interval '1201 seconds' where user_id='a2200000-0000-4000-8000-000000000001';
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining','2','Two elapsed ticks');
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining','2','Fractions preserved');
update access_policy set policy=jsonb_set(policy,'{energyRefillSeconds}','60');
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining','2','Changed rate never grants retroactive ticks');
select ok((select revision>1 from access_policy),'Policy revision increments');
insert into entitlements(user_id,entitlement,active,expires_at,store) values('a2200000-0000-4000-8000-000000000001','premium',true,now()+interval '1 day','manual');
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'remaining',null,'Paid tier unlimited');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','paid','{"kind":"fixture"}',200,6)->>'reason','allowed','Paid access');
select is((select balance from access_energy where user_id='a2200000-0000-4000-8000-000000000001'),2,'Paid run consumes no free balance');
update entitlements set expires_at=now()-interval '1 second' where user_id='a2200000-0000-4000-8000-000000000001';
select is(access_status('a2200000-0000-4000-8000-000000000001')->>'tier','free','Expired subscription is free');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','paid','{"kind":"fixture"}',200,6)->>'reason','allowed','Already authorized run survives expiry');
select is(reserve_access('a2200000-0000-4000-8000-000000000001','after','{"kind":"fixture"}',12,1)->>'reason','limit','New run obeys free limits');
set local role anon;
select throws_ok('select * from access_policy','42501',null,'Guest cannot directly read policy');
select throws_ok('select * from access_grants','42501',null,'Guest cannot read grants');
select throws_ok('select * from access_energy','42501',null,'Guest cannot read balances');
select throws_ok('select * from cancellation_requests','42501',null,'Guest cannot read PII');
reset role;
set local role authenticated;
select throws_ok($$select access_status('a2200000-0000-4000-8000-000000000001')$$,'42501',null,'Only service uses trusted RPC');
select throws_ok($$select reserve_access('a2200000-0000-4000-8000-000000000001','forged','{}',1,0)$$,'42501',null,'Client cannot forge source cost');
select throws_ok('update access_policy set policy=''{}''','42501',null,'Client cannot activate checkout');
select throws_ok('select * from cancellation_requests','42501',null,'Account cannot enumerate declarations');
reset role;
select is(receive_cancellation('c2200000-0000-4000-8000-000000000001','{"email":"fixture@example.invalid","name":"Fixture"}')->>'status','received','Receipt is not provider cancellation');
select is(receive_cancellation('c2200000-0000-4000-8000-000000000001','{"email":"fixture@example.invalid","name":"Fixture"}')->>'status','received','Declaration retry');
select is((select count(*)::integer from cancellation_requests where id='c2200000-0000-4000-8000-000000000001'),1,'One declaration');
select throws_ok($$select receive_cancellation('c2200000-0000-4000-8000-000000000001','{"email":"fixture@example.invalid","name":"Changed"}')$$,'P0001','Cancellation conflict','Immutable receipt');
delete from auth.users where id='a2200000-0000-4000-8000-000000000001';
select is((select count(*)::integer from access_energy where user_id='a2200000-0000-4000-8000-000000000001'),0,'Account balance cascades');
select is((select count(*)::integer from access_grants where user_id='a2200000-0000-4000-8000-000000000001'),0,'Account grants cascade');
select * from finish();
rollback;
